#!/usr/bin/env python3
"""Build the ADR-0039 all-specialist comparison, final-state register, and handoff."""
from __future__ import annotations

import json
from collections import Counter
from pathlib import Path

from artifact_ledger import atomic_write, content_hash, pretty_bytes
from specialist_shadow_calibration_runtime import ROOT

OUTPUT = ROOT / "fixtures" / "specialist-program-retrospective" / "2026-08-03" / "adr0039"
WAVES = [
    (1, "fixtures/specialist-static-evidence-increment1/evidence/2026-08-03/adr0039/gx10-live-run-001/live-run/summary.json"),
    (2, "fixtures/specialist-build-supply-chain-increment2/evidence/2026-08-03/adr0039/gx10-live-run-001/live-run/summary.json"),
    (3, "fixtures/specialist-k8s-secure-increment34/evidence/2026-08-03/adr0039/gx10-live-run-001/live-run/summary.json"),
    (5, "fixtures/specialist-increment567/evidence/2026-08-03/adr0039/gx10-live-run-001/summary.json"),
]
INCREMENTS = {
    "SPEC-DEPS":1,"SPEC-SBOM":1,"SPEC-LINT":1,"SPEC-CONTAINER":2,"SPEC-CICD":2,"SPEC-IAC":2,
    "SPEC-K8S-WORKLOAD":3,"SPEC-K8S-PLATFORM":3,"SPEC-COMMS":3,"SPEC-SECURE-CODE":4,"SPEC-SECRETS":4,
    "SPEC-ARCH":5,"SPEC-INTEROP":5,"SPEC-DATA":5,"SPEC-DIAGRAM":5,"SPEC-IO":5,
    "SPEC-OBS":6,"SPEC-PERF":6,"SPEC-FMECA":6,"SPEC-RESEARCH":7,"SPEC-RISK":7,"SPEC-SECURITY":7,
}

def load(path: str | Path):
    return json.loads((ROOT / path).read_text(encoding="utf-8"))

def build() -> dict:
    results, wave_metrics = {}, []
    for wave, path in WAVES:
        summary=load(path); assert summary["passed"] is True
        input_tokens=sum(x["usage"]["input_tokens"] for x in summary["results"]); output_tokens=sum(x["usage"]["output_tokens"] for x in summary["results"])
        wave_metrics.append({"wave":wave,"summary":path,"roles":len(summary["results"]),"input_tokens":input_tokens,"output_tokens":output_tokens,"passed":True})
        for item in summary["results"]: results[item["designation"]]=(path,item)
    registered=[x for x in load("agents/agent-identities.json")["agents"] if x["designation"].startswith("SPEC-")]
    assert len(registered)==22 and set(results)=={x["designation"] for x in registered}
    states=[]
    for identity in sorted(registered,key=lambda x:(INCREMENTS[x["designation"]],x["designation"])):
        designation=identity["designation"]; source,item=results[designation]
        states.append({"designation":designation,"agent_uuid":identity["agent_uuid"],"increment":INCREMENTS[designation],"construction_state":"model_calibration_passed","final_state":"blocked_on_evidence","candidate_complete":False,"blocking_evidence":["independent human shadow-review response","qualified semantic adjudication","project-owner candidate disposition"],"machine_evidence":{"summary":source,"raw_response_hash":item["raw_response_hash"],"artifact_hash":item["artifact_hash"],"packet_hash":item["packet_hash"]},"lifecycle":{"comparison_only":True,"scheduled":False,"product_fan_in_eligible":False,"report_eligible":False,"deployment_authorized":False,"a100_production_authorized":False}})
    register={"schema_version":"1.0.0","program":"ADR-0039 specialist candidate buildout","as_of":"2026-08-03","state_definitions":{"candidate_complete":"all machine, human-review, adjudication, and owner-disposition evidence complete","revision_required":"an identified candidate defect requires correction","blocked_on_evidence":"candidate construction passed but required semantic evidence is absent","retained_only":"retained for lineage with no active completion path"},"states":states,"counts":dict(Counter(x["final_state"] for x in states)),"human_review":{"state":"pending_consolidated_end_of_program_wave","responses_observed":0,"qualified_adjudications_observed":0,"owner_candidate_dispositions_observed":0},"lifecycle":{"scheduled":False,"product_fan_in_eligible":False,"deployment_authorized":False,"a100_production_authorized":False}}
    register["register_hash"] = content_hash(register)
    comparison={"schema_version":"1.0.0","program":"ADR-0039 specialist candidate buildout","result":"machine_preparation_complete_human_review_pending","coverage":{"registered_specialists":22,"constructed_candidates":22,"gx10_model_calibrations_passed":22,"strict_role_payloads_retained":22,"focus_bindings_validated":22,"human_responses":0,"qualified_adjudications":0},"usage":{"model":"qwen3-32b","platform":"GX-10 / approved DGX Spark-equivalent","input_tokens":sum(x["input_tokens"] for x in wave_metrics),"output_tokens":sum(x["output_tokens"] for x in wave_metrics),"cost_usd_reported":0.0,"wave_metrics":wave_metrics,"timing_limitations":["Comparable per-role latency was not retained across every wave.","The Increment 5-7 remote command took 512.3 seconds including transfer, regression, inference, packaging, and hashing; it is not a pure model-latency measurement.","No A100 timing or throughput claim is inferred from GX-10 execution."]},"cross_agent_relationships":[{"group":"inventory","agents":["SPEC-DEPS","SPEC-SBOM","SPEC-LINT"],"preserved_distinction":"dependency health, inventory completeness, and rule execution remain separate"},{"group":"delivery","agents":["SPEC-CONTAINER","SPEC-CICD","SPEC-IAC"],"preserved_distinction":"definition, artifact, pipeline, desired state, and observed deployment are not collapsed"},{"group":"kubernetes_trust","agents":["SPEC-K8S-WORKLOAD","SPEC-K8S-PLATFORM","SPEC-COMMS"],"preserved_distinction":"workload, shared platform, and traffic-path authority remain separate"},{"group":"design_and_resources","agents":["SPEC-ARCH","SPEC-INTEROP","SPEC-DATA","SPEC-DIAGRAM","SPEC-IO"],"preserved_distinction":"intended structure, interfaces, information, model quality, and external interactions retain source meanings"},{"group":"operability","agents":["SPEC-OBS","SPEC-PERF","SPEC-FMECA"],"preserved_distinction":"signals, measured behavior, failure propagation, and recovery evidence are distinct"},{"group":"synthesis","agents":["SPEC-RESEARCH","SPEC-RISK","SPEC-SECURITY"],"preserved_distinction":"source authority, risk characterization, and security posture cannot manufacture acceptance or release authority"}],"observed_harness_lessons":["Strict schemas and evidence-reference validation constrain structure; they do not provide semantic approval.","Protected focus-profile material kept overlapping roles distinguishable while a shared universal envelope preserved harness interoperability.","Static configuration consistently required configured_not_demonstrated or not_assessed effectiveness.","Synthesis-sensitive roles can consume content-addressed child candidates while preserving child identifiers and unknowns.","Transport and package completeness must be tested before inference; fail-closed regressions caught a missing pyproject.toml before model execution.","Raw model payloads must remain separate from deterministic projection, locators, lifecycle controls, and human packets.","Credentials can be streamed without retention; all retrieved Increment 5-7 evidence had zero exact-key and restricted-marker matches."],"human_metrics":{"state":"not_yet_observable","reason":"project owner directed all human review to the end of candidate construction","must_not_be_fabricated":["semantic faithfulness","false-positive rate","partial-support rate","reviewer agreement","reproduction time","review usefulness"]},"next_gate":"execute the consolidated human shadow-review wave, qualified adjudication, and project-owner dispositions; any scheduling or fan-in requires a separate ADR","final_state_register":"final-state-register.json"}
    comparison["comparison_hash"] = content_hash(comparison)
    summary={"suite":"adr0039-increment8-cross-agent-retrospective","passed":True,"machine_preparation_complete":True,"human_review_pending":True,"registered_agents":22,"gx10_passed":22,"input_tokens":comparison["usage"]["input_tokens"],"output_tokens":comparison["usage"]["output_tokens"],"final_state_counts":register["counts"],"scheduled":False,"product_fan_in_eligible":False,"deployment_authorized":False,"a100_production_authorized":False}
    atomic_write(OUTPUT/"final-state-register.json",pretty_bytes(register)); atomic_write(OUTPUT/"all-agent-comparison.json",pretty_bytes(comparison)); atomic_write(OUTPUT/"summary.json",pretty_bytes(summary))
    retro=f"""# ADR-0039 Specialist Program Retrospective\n\n## Outcome\n\nCandidate construction and GX-10 model calibration are complete for all 22 registered specialist agents. Every live role payload passed its strict schema, focus binding, admitted-evidence, deterministic projection, locator, and comparison-only lifecycle gates. The program consumed {comparison['usage']['input_tokens']:,} input tokens and {comparison['usage']['output_tokens']:,} output tokens.\n\nThis is machine preparation, not semantic completion. All 22 candidates are `blocked_on_evidence` because the consolidated human responses, qualified adjudications, and project-owner candidate dispositions do not yet exist. None is scheduled, eligible for product fan-in or reports, deployed, or authorized for A100 production.\n\n## What worked\n\n- A common envelope made every role interoperable with the same harness while strict role schemas kept domain output distinct.\n- Focus profiles were hash-bound and compression-protected, preventing generic prompt reduction from erasing each specialist's authoritative questions.\n- Evidence tiers stopped source and configuration from becoming claims of runtime effectiveness.\n- Content-addressed child artifacts let `SPEC-RISK` and `SPEC-SECURITY` synthesize prior work without flattening source identifiers or inventing authority.\n- Fail-closed pre-inference tests caught a GX-10 package omission before new inference began.\n- The rotated key was streamed only for execution; the retained Increment 5-7 evidence contains zero exact-key or restricted-marker matches.\n\n## What we learned\n\nSchema validity is necessary but not sufficient. The harness can prove identity, provenance, evidence reference validity, lifecycle authority, and output shape; a qualified human must still judge whether a claim is semantically faithful and useful. Static evidence repeatedly showed why `configured_not_demonstrated` is an important state. The role prompts also need protected domain questions, evidence priorities, forbidden inferences, unknown-preservation rules, and authority boundaries—not merely a role title.\n\nThe largest unresolved measurement gap is human usefulness. We cannot yet report semantic fidelity, false-positive rate, reviewer agreement, or reproduction time. Latency instrumentation also needs a common per-role clock before comparing waves or projecting A100 performance.\n\n## Corrective priorities\n\n1. Run the consolidated human shadow-review dataset with general, restricted, and qualified tracks.\n2. Adjudicate representative disagreements and record project-owner dispositions for every candidate.\n3. Add uniform request, first-token, completion, retry, and projection timing to every live run.\n4. Turn reviewer evidence requests and semantic defects into prompt, schema, rubric, or evidence-adapter revisions.\n5. Propose any product fan-in, scheduling, deployment, or A100 production evaluation through a separate ADR with rollback.\n"""
    handoff="""# Consolidated Human Shadow-Review Handoff\n\nReview all 22 packets as comparison-only candidate material. Reproduce each claim from its exact revision, path, line, excerpt, and hash. Score semantic faithfulness, support level, clarity, scope discipline, and usefulness; request missing evidence explicitly. Do not infer acceptance from schema validity or reviewer consensus.\n\nGeneral engineering interns may review public, sanitized packets for traceability and clarity. Secret-related material remains restricted; risk magnitude, security posture, architectural intent, data-governance meaning, and source authority require qualified adjudication. Reviewer responses never schedule, approve, release, deploy, or accept risk.\n\nAfter independent responses are retained, qualified adjudicators must preserve disagreements and identify eligible gold or negative examples. The project owner then records one disposition per candidate: revise, continue calibration, candidate-complete, or retained-only.\n"""
    atomic_write(OUTPUT/"retrospective.md",retro.encode()); atomic_write(OUTPUT/"human-review-handoff.md",handoff.encode()); return summary

if __name__ == "__main__": print(json.dumps(build(),indent=2,sort_keys=True))
